// \u521D\u59CB\u5316
onMounted(() => {
  // \u521D\u59CB\u5316\u97F3\u4E50\u6570\u636E\uFF08\u5982\u679C\u8FD8\u6CA1\u6709\u52A0\u8F7D\uFF09
  if (store.music.songs.length === 0) {
    initMusicData();
  }

  // \u5982\u679C\u6709\u6B4C\u66F2\u4F46\u8FD8\u6CA1\u6709\u52A0\u8F7D\u4EFB\u4F55\u6B4C\u66F2\uFF0C\u968F\u673A\u9009\u62E9\u4E00\u9996
  if (store.music.songs.length > 0 && !store.music.isPlaying && store.music.currentTime === 0) {
    const randomIndex = Math.floor(Math.random() * store.music.songs.length);
    musicLoadSong(randomIndex);
  }

  // \u5C1D\u8BD5\u4ECE\u89D2\u8272\u53D8\u91CF\u8BFB\u53D6\u7528\u6237\u6570\u636E
  try {
    const charVars = getVariables({ type: 'character' });
    const phoneData = _.get(charVars, 'phone_data');
    if (phoneData?.user) {
      if (phoneData.user.name) userData.value.name = phoneData.user.name;
      if (phoneData.user.avatar) userData.value.avatar = phoneData.user.avatar;
    }
  } catch (e) {
    console.warn('[ListenTogether] \u65E0\u6CD5\u52A0\u8F7D\u7528\u6237\u6570\u636E:', e);
  }

  // \u542F\u52A8\u4E00\u8D77\u542C\u8BA1\u65F6\u5668\uFF08\u53EA\u8981\u9875\u9762\u6253\u5F00\u5C31\u6301\u7EED\u8BA1\u65F6\uFF09
  listenTogetherTimer = setInterval(() => {
    listenTogetherDuration.value++;
  }, 1000);

  // \u8BBE\u7F6E\u6B4C\u66F2\u5B8C\u6210\u56DE\u8C03\uFF08\u53EA\u6709\u5B8C\u6574\u64AD\u653E\u5230\u7ED3\u675F\u624D\u7D2F\u79EF\uFF09
  setOnSongEndedCallback(() => {
    completedSongsCount.value++;
  });

  // \u52A0\u8F7D\u804A\u5929\u5386\u53F2
  loadChatHistory();
});

onUnmounted(() => {
  stopVolumeDrag();
  // \u6E05\u7406\u8BA1\u65F6\u5668
  if (listenTogetherTimer) {
    clearInterval(listenTogetherTimer);
    listenTogetherTimer = null;
  }
  // \u6E05\u7406\u6B4C\u66F2\u5B8C\u6210\u56DE\u8C03
  setOnSongEndedCallback(null);
  // \u6E05\u7406\u8BED\u97F3\u6253\u5B57\u5B9A\u65F6\u5668
  stopVoiceTyping();
});
