type ChatGalleryItem = {
  url: string;
  content: string;
};

const CHAT_CAMERA_GALLERY_KEY = 'phone_camera_gallery';
const chatGalleryItems = ref<ChatGalleryItem[]>([]);

function normalizeChatGalleryItem(input: unknown): ChatGalleryItem | null {
  if (!input || typeof input !== 'object') return null;
  const url = String((input as any).url ?? '').trim();
  if (!url) return null;
  const content = String((input as any).content ?? '').trim();
  return { url, content };
}

function loadChatGalleryFromVariables(): ChatGalleryItem[] {
  try {
    const chatVars = getVariables({ type: 'chat' }) || {};
    const raw = _.get(chatVars, CHAT_CAMERA_GALLERY_KEY);
    if (!Array.isArray(raw)) return [];
    return raw.map(normalizeChatGalleryItem).filter(Boolean) as ChatGalleryItem[];
  } catch (e) {
    console.warn('[ChatDetail] \u8BFB\u53D6\u804A\u5929\u56FE\u5E93\u5931\u8D25(\u5FFD\u7565):', e);
    return [];
  }
}

const sendGalleryImage = (item: ChatGalleryItem) => {
  const url = String(item?.url || '').trim();
  if (!url) return;

  const timeString = getNowTimeString();
  messages.value.push({
    id: Date.now().toString(),
    type: 'image',
    content: url,
    description: String(item?.content || '').trim() || undefined,
    time: timeString,
    isMe: true,
    isNewMessage: true,
  });

  showGalleryPicker.value = false;
  activeFunction.value = null;
  scrollToBottom();
};

const functionScrollRef = ref<HTMLElement | null>(null);
const functionBarDragging = ref(false);
const functionBarPointerDown = ref(false);
const functionBarIgnoreClickUntil = ref(0);
let functionBarDragStartX = 0;
let functionBarDragStartScrollLeft = 0;
let functionBarActivePointerId: number | null = null;

type FunctionItemKey = 'sticker' | 'emoji' | 'voice' | 'image' | 'gallery' | 'file' | 'transfer' | 'listen-together';

const onFunctionItemClick = (key: FunctionItemKey) => {
  if (Date.now() < functionBarIgnoreClickUntil.value) return;
  if (key === 'listen-together') {
    toggleFunction('listen-together');
    return;
  }
  toggleFunction(key);
};

const onFunctionBarPointerDown = (e: PointerEvent) => {
  if (e.pointerType !== 'mouse') return;
  if (e.button !== 0) return;
  const el = functionScrollRef.value;
  if (!el) return;
  functionBarPointerDown.value = true;
  functionBarDragging.value = false;
  functionBarDragStartX = e.clientX;
  functionBarDragStartScrollLeft = el.scrollLeft;
  functionBarActivePointerId = e.pointerId;
};

const onFunctionBarPointerMove = (e: PointerEvent) => {
  if (!functionBarPointerDown.value) return;
  if (functionBarActivePointerId !== e.pointerId) return;
  const el = functionScrollRef.value;
  if (!el) return;
  const dx = e.clientX - functionBarDragStartX;
  if (!functionBarDragging.value && Math.abs(dx) > 6) {
    functionBarDragging.value = true;
    functionBarIgnoreClickUntil.value = Date.now() + 350;
  }
  if (functionBarDragging.value) {
    el.scrollLeft = functionBarDragStartScrollLeft - dx;
    e.preventDefault();
  }
};

const onFunctionBarPointerUp = (e: PointerEvent) => {
  if (!functionBarPointerDown.value) return;
  if (functionBarActivePointerId !== null && functionBarActivePointerId !== e.pointerId) return;
  functionBarPointerDown.value = false;
  functionBarDragging.value = false;
  functionBarActivePointerId = null;
};

