const getFileExtensionClass = (filename?: string) => {
  if (!filename) return 'unknown';
  if (!filename.includes('.')) return 'unknown';
  const ext = filename.split('.').pop()?.toLowerCase() || '';
  switch (ext) {
    case 'doc':
    case 'docx':
      return 'docx';
    case 'ppt':
    case 'pptx':
      return 'pptx';
    case 'xls':
    case 'xlsx':
      return 'xlsx';
    case 'rar':
    case '7z':
    case 'zip':
      return 'zip';
    case 'pdf':
      return 'pdf';
    default:
      return 'unknown';
  }
};

